+    pub(crate) fn eat_if_next(&mut self, accept: impl FnOnce(Token) -> bool) -> bool {
+        let checkpoint = self.lexer.checkpoint();
+        let next = self.lexer.next_token();
+        if !accept(next) {
+            self.lexer.rewind(checkpoint);
+            return false;
+        }
