204	    /// Try to detect: `const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(...)`
205	    pub(super) fn try_forward_ref<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
206	        let init = decl.init.as_ref()?;
207	        let call = match peel_expr(init) {
208	            Expression::CallExpression(ce) => ce,
209	            _ => return None,
210	        };
211	        if !self.is_forward_ref_call(call) {
212	            return None;
213	        }
214	
215	        // forwardRef<RefType, PropsType>(fn) — PropsType is the second type parameter
216	        let type_params = call.type_arguments.as_ref()?;
217	        if type_params.params.len() < 2 {
218	            return None;
219	        }
220	        let props_type = &type_params.params[1];
221	        let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
222	
223	        // The render function is forwardRef's call argument — its first parameter is
224	        // props (the second is `ref`, which never carries destructured defaults we care about).
225	        let render_params = match call.arguments.first() {
226	            Some(Argument::FunctionExpression(fe)) => Some(&fe.params),
227	            Some(Argument::ArrowFunctionExpression(afe)) => Some(&afe.params),
228	            _ => None,
229	        };
230	        let param_defaults = render_params.map(|p| self.extract_param_defaults(p)).unwrap_or_default();
231	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
232	
233	        Some(
234	            ComponentMapping::new(
235	                name.to_owned(),
236	                props_name,
237	                self.file_path.clone(),
238	                decl.span.start,
239	                decl.span.end,
240	                DetectionRule::ForwardRef,
241	            )
242	            .with_props_type_args(type_args)
243	            .with_doc(description, tags)
244	            .with_param_defaults(param_defaults),
245	        )
246	    }
247	
248	    /// Try to detect: `const Button = ({ variant }: ButtonProps) => ...` and the `function` expression form. The
249	    /// function must show it renders (see `evidence`): a typed first parameter alone also describes helpers such as
250	    /// `FormatName = (u: User) => string`. A first parameter that is not a named type is not a props object.
251	    pub(super) fn try_typed_function_expression<'a>(
252	        &mut self,
253	        decl: &Binding<'_, 'a>,
254	        name: &str,
255	    ) -> Option<ComponentMapping> {
256	        let (params, shape) = match peel_expr(decl.init.as_ref()?) {
257	            Expression::ArrowFunctionExpression(afe) => (&*afe.params, FunctionShape::of_arrow(afe)),
258	            Expression::FunctionExpression(fe) => (&*fe.params, FunctionShape::of_function(fe)),
259	            _ => return None,
260	        };
261	        let type_ann = params.items.first()?.type_annotation.as_ref()?;
262	        if let Err(reason) = renders(&shape, &*self) {
263	            self.decline_reason = Some(format!("'{name}' takes a typed props parameter but {reason}"));
264	            return None;
265	        }
266	        let (props_name, type_args) = self.extract_type_name_from_type(&type_ann.type_annotation)?;
267	        let param_defaults = self.extract_param_defaults(params);
268	        let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
269	        Some(
270	            ComponentMapping::new(
271	                name.to_owned(),
272	                props_name,
273	                self.file_path.clone(),
274	                decl.span.start,
275	                decl.span.end,
276	                DetectionRule::TypedFunctionExpression,
277	            )
278	            .with_props_type_args(type_args)
279	            .with_doc(description, tags)
280	            .with_param_defaults(param_defaults),
281	        )
282	    }
283	
284	    /// Try to detect: `const Button = anyHOC(function Button(props: ButtonProps) {...})`
285	    pub(super) fn try_hoc_wrapped<'a>(&mut self, decl: &Binding<'_, 'a>, name: &str) -> Option<ComponentMapping> {
286	        let init = decl.init.as_ref()?;
287	        let call = match peel_expr(init) {
288	            Expression::CallExpression(ce) => ce,
289	            _ => return None,
290	        };
291	
292	        // First arg should be a function with a typed props param — or a forwardRef() call.
293	        let first_arg = call.arguments.first()?;
294	
295	        // `memo(forwardRef(…))`: the props come from forwardRef's type arguments, or from its render function.
296	        if let Argument::CallExpression(inner) = first_arg {
297	            if !self.is_forward_ref_call(inner) {
298	                return None;
299	            }
300	            // `forwardRef<Ref, Props>(…)` names the props in its second type argument; otherwise the render function's
301	            // first parameter does. A call with one type argument and no function (`forwardRef<Ref>()`) names neither.
302	            let props_type = inner.type_arguments.as_ref().and_then(|type_params| type_params.params.get(1));
303	            let Some(props_type) = props_type else {
304	                let render = inner.arguments.first()?;
305	                return self.mapping_from_typed_function(decl, name, call, render, DetectionRule::ForwardRef);
306	            };
307	            let (props_name, type_args) = self.extract_type_name_from_type(props_type)?;
308	            let (description, tags) = self.find_jsdoc_with_tags(decl.span.start);
309	            return Some(
310	                ComponentMapping::new(
311	                    name.to_owned(),
312	                    props_name,
313	                    self.file_path.clone(),
314	                    decl.span.start,
315	                    decl.span.end,
316	                    DetectionRule::ForwardRef,
317	                )
318	                .with_props_type_args(type_args)
319	                .with_doc(description, tags),
320	            );
321	        }
322	        let rule = if self.is_forward_ref_call(call) { DetectionRule::ForwardRef } else { DetectionRule::HocWrapper };
323	        self.mapping_from_typed_function(decl, name, call, first_arg, rule)
324	    }
