"""Compare `extract --json` of two builds on the corpora: JSON parsed, `stats` dropped."""
import json, os, subprocess, sys

ROOT = '/Users/gabe/.cache/caliper/corpora/repos'
CORPORA = {
    'mantine': 'mantine/packages/@mantine/core/src',
    'chakra': 'chakra-ui/packages/react/src',
    'shadcn': 'shadcn-ui/apps/v4',
    'antd': 'ant-design/components',
    'spectrum': 'react-spectrum/packages',
}
BUILDS = {
    'base': '/tmp/claude-501/target-base/release/caliper-docgen',
    'head': '/Users/gabe/Projects/caliper/.claude/worktrees/agent-a5bd7e81f4fe71658/target/release/caliper-docgen',
}
OUT = '/tmp/claude-501/oxc-diff'
os.makedirs(OUT, exist_ok=True)


def run(build, corpus):
    path = f'{OUT}/{corpus}.{build}.json'
    if not os.path.exists(path):
        args = [BUILDS[build], 'extract', '--src', f'{ROOT}/{CORPORA[corpus]}', '--quiet', '--no-cache',
                '--load-dependencies', '--json']
        done = subprocess.run(args, capture_output=True, text=True)
        if done.returncode != 0:
            print(corpus, build, 'exit', done.returncode, done.stderr[-2000:])
        with open(path, 'w') as f:
            f.write(done.stdout)
    with open(path) as f:
        return json.load(f)


def degraded(output):
    """Diagnostics saying the semantic backend did not run cleanly: code SEMANTIC_BACKEND, severity not info."""
    found = []

    def walk(node):
        if isinstance(node, dict):
            code = node.get('code')
            if isinstance(code, str) and code.upper().replace('-', '_') in ('SEMANTIC_BACKEND', 'SEMANTICBACKEND') \
                    and str(node.get('severity', '')).lower() != 'info':
                found.append((code, node.get('severity')))
            for value in node.values():
                walk(value)
        elif isinstance(node, list):
            for value in node:
                walk(value)

    walk(output)
    return found


def first_difference(a, b, path='$'):
    if type(a) is not type(b):
        return path, a, b
    if isinstance(a, dict):
        for key in sorted(set(a) | set(b)):
            if key not in a or key not in b:
                return f'{path}.{key}', a.get(key, '<missing>'), b.get(key, '<missing>')
            found = first_difference(a[key], b[key], f'{path}.{key}')
            if found:
                return found
        return None
    if isinstance(a, list):
        if len(a) != len(b):
            return f'{path}[len]', len(a), len(b)
        for i, (x, y) in enumerate(zip(a, b)):
            found = first_difference(x, y, f'{path}[{i}]')
            if found:
                return found
        return None
    return None if a == b else (path, a, b)


status = 0
for corpus in (sys.argv[1:] or CORPORA):
    outputs = {}
    for build in BUILDS:
        output = run(build, corpus)
        if isinstance(output, dict):
            output.pop('stats', None)
        outputs[build] = output
    bad = {build: degraded(output) for build, output in outputs.items()}
    if any(bad.values()):
        print(corpus, 'DROPPED (semantic backend degraded):', bad)
        continue
    difference = first_difference(outputs['base'], outputs['head'])
    count = len(outputs['head'].get('components', [])) if isinstance(outputs['head'], dict) else '?'
    if difference:
        status = 1
        print(corpus, 'DIFFERS at', difference[0], '\n  base:', str(difference[1])[:600], '\n  head:', str(difference[2])[:600])
    else:
        print(corpus, 'identical; top-level keys', sorted(outputs['head']) if isinstance(outputs['head'], dict) else '?',
              'components', count)
sys.exit(status)

